const EXCLUIR_DOMINIOS = ['SEU_DOMINIO_INTERNO'];
const EXCLUIR_EMAILS = ['email_a_excluir@exemplo.com'];
const LIMITE = 10;

function excluir(email) {
  const dominio = email.split('@')[1] || '';
  return EXCLUIR_EMAILS.includes(email) || EXCLUIR_DOMINIOS.some(d => dominio.includes(d));
}

return $input.all().flatMap(item => {
  const ev = item.json;
  const emails = [...new Set(
    (ev.attendees || [])
      .filter(p => !p.resource && p.responseStatus !== 'declined')
      .map(p => (p.email || '').trim().toLowerCase())
      .filter(email => email && !excluir(email))
  )];

  if (emails.length >= LIMITE) return [];

  return emails.map(email => ({
    json: { id: ev.id, summary: ev.summary, email }
  }));
});
